+
+    public static function validCsrf($session, $token)
+    {
+        return is_string($token) && isset($session['csrf_token']) && is_string($session['csrf_token'])
+            && strlen($session['csrf_token']) === 64 && hash_equals($session['csrf_token'], $token);
+    }
